use rust_ordo_ext::PreloadPlanner;

fn main() {
    let mut planner = PreloadPlanner::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let input = line.unwrap();
        let parts: Vec<&str> = input.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        match parts[0] {
            "connect" => {
                if parts.len() >= 3 {
                    planner.connect(parts[1], parts[2]);
                }
            }
            "preload" => {
                if parts.len() >= 3 {
                    let node = parts[1];
                    let depth: usize = parts[2].parse().unwrap();
                    let preload = planner.preload_from(node, depth);
                    println!("preload={}", preload.join(","));
                }
            }
            _ => {}
        }
    }
}
